@page "/settings"
@namespace sv_279b0a141af14c3f9699aa5554977309.Components.Pages.Settings
@rendermode InteractiveServer
@using sv_279b0a141af14c3f9699aa5554977309.Components.Pages.Settings

<PageTitle>Settings</PageTitle>

<div class="settings-page">
    <SettingsSidebar ActiveSection="@_activeSection" OnSectionChanged="SetActiveSection" />

    <main class="settings-content">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection />
                break;
            case "Notifications":
                <NotificationsSection />
                break;
            case "Security":
                <SecuritySection />
                break;
            case "Appearance":
                <AppearanceSection />
                break;
        }
    </main>
</div>

@code {
    private string _activeSection = "Profile";

    private void SetActiveSection(string section)
    {
        _activeSection = section;
    }
}

/* Settings Page Layout */
.settings-page {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

/* Sidebar */
.settings-sidebar {
    width: 240px;
    background: #f8f9fa;
    border-right: 1px solid #e0e0e0;
    padding: 1.5rem 0;
    flex-shrink: 0;
}

.sidebar-title {
    padding: 0 1.5rem;
    margin: 0 0 1rem;
    font-size: 1.25rem;
    font-weight: 600;
    color: #333;
}

.sidebar-nav {
    list-style: none;
    padding: 0;
    margin: 0;
}

.sidebar-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.5rem;
    cursor: pointer;
    color: #555;
    transition: background-color 0.15s, color 0.15s;
    border-left: 3px solid transparent;
}

.sidebar-item:hover {
    background: #e9ecef;
    color: #333;
}

.sidebar-item.active {
    background: #e7f1ff;
    color: #0d6efd;
    border-left-color: #0d6efd;
    font-weight: 500;
}

.sidebar-icon {
    font-size: 1.1rem;
}

/* Main Content */
.settings-content {
    flex: 1;
    padding: 2rem;
    max-width: 800px;
}

.settings-section h3 {
    margin: 0 0 1.5rem;
    font-size: 1.5rem;
    font-weight: 600;
    color: #333;
}

/* Form Controls */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.375rem;
    font-weight: 500;
    color: #444;
}

.form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 0.375rem;
    font-size: 0.95rem;
    transition: border-color 0.15s;
    box-sizing: border-box;
}

.form-control:focus {
    outline: none;
    border-color: #0d6efd;
    box-shadow: 0 0 0 2px rgba(13, 110, 253, 0.15);
}

/* Buttons */
.btn {
    padding: 0.5rem 1rem;
    border: none;
    border-radius: 0.375rem;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    transition: background-color 0.15s;
}

.btn-primary {
    background: #0d6efd;
    color: white;
}

.btn-primary:hover {
    background: #0b5ed7;
}

.btn-secondary {
    background: #6c757d;
    color: white;
}

.btn-secondary:hover {
    background: #5c636a;
}

.btn-outline {
    background: transparent;
    border: 1px solid #ced4da;
    color: #333;
}

.btn-outline:hover {
    background: #f8f9fa;
}

.btn-danger {
    background: #dc3545;
    color: white;
}

.btn-danger:hover {
    background: #bb2d3b;
}

.btn-sm {
    padding: 0.25rem 0.5rem;
    font-size: 0.8rem;
}

.form-actions {
    margin-top: 1.5rem;
    display: flex;
    gap: 0.75rem;
}

/* Toast */
.toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 0.375rem;
    font-size: 0.9rem;
    animation: slideIn 0.3s ease;
}

.toast.success {
    background: #d1e7dd;
    color: #0f5132;
    border: 1px solid #badbcc;
}

@keyframes slideIn {
    from { opacity: 0; transform: translateY(-10px); }
    to { opacity: 1; transform: translateY(0); }
}

/* Profile */
.avatar-preview {
    text-align: center;
    margin-bottom: 1.5rem;
}

.avatar-image {
    width: 100px;
    height: 100px;
    border-radius: 50%;
    object-fit: cover;
    border: 3px solid #e0e0e0;
}

.avatar-url {
    margin-top: 0.5rem;
    font-size: 0.8rem;
    color: #666;
    word-break: break-all;
}

/* Toggles */
.toggle-group {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.toggle-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    cursor: pointer;
}

.toggle-item input[type="checkbox"] {
    width: 1.1rem;
    height: 1.1rem;
    accent-color: #0d6efd;
}

/* Channels */
.channels-section {
    margin-top: 2rem;
}

.channels-section h4 {
    margin-bottom: 0.75rem;
    font-size: 1rem;
    color: #444;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.375rem 0;
    cursor: pointer;
}

/* Security */
.password-panel {
    margin-bottom: 2rem;
}

.password-form {
    margin-top: 1rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 0.5rem;
    border: 1px solid #e0e0e0;
}

.error-message {
    color: #dc3545;
    font-size: 0.875rem;
    margin: 0.5rem 0;
}

.success-message {
    color: #0f5132;
    font-size: 0.875rem;
    margin: 0.5rem 0;
}

.twofa-section {
    margin-bottom: 2rem;
}

.twofa-section h4 {
    margin-bottom: 0.75rem;
}

.status-indicator {
    display: inline-block;
    padding: 0.25rem 0.75rem;
    border-radius: 1rem;
    font-size: 0.8rem;
    font-weight: 500;
    margin-bottom: 0.75rem;
}

.status-indicator.enabled {
    background: #d1e7dd;
    color: #0f5132;
}

.status-indicator.disabled {
    background: #f8d7da;
    color: #842029;
}

.twofa-status {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

/* Sessions Table */
.sessions-section h4 {
    margin-bottom: 0.75rem;
}

.sessions-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.9rem;
}

.sessions-table th,
.sessions-table td {
    padding: 0.625rem 0.75rem;
    text-align: left;
    border-bottom: 1px solid #e0e0e0;
}

.sessions-table th {
    background: #f8f9fa;
    font-weight: 600;
    color: #444;
}

.current-badge {
    font-size: 0.75rem;
    background: #e7f1ff;
    color: #0d6efd;
    padding: 0.2rem 0.5rem;
    border-radius: 0.25rem;
}

/* Modal */
.modal-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.modal-dialog {
    background: white;
    padding: 1.5rem;
    border-radius: 0.5rem;
    max-width: 400px;
    width: 90%;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.2);
}

.modal-dialog h4 {
    margin: 0 0 1rem;
}

.modal-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
    justify-content: flex-end;
}

/* Appearance */
.radio-group {
    display: flex;
    gap: 1.5rem;
}

.radio-group label {
    display: flex;
    align-items: center;
    gap: 0.375rem;
    cursor: pointer;
    font-weight: normal;
}

/* Preview Area */
.preview-area {
    margin-top: 2rem;
    padding: 1.5rem;
    border: 2px dashed #ced4da;
    border-radius: 0.5rem;
    transition: all 0.3s ease;
}

.preview-area h4 {
    margin: 0 0 0.75rem;
    font-size: 1rem;
}

.preview-card {
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 0.375rem;
    margin-top: 0.75rem;
}

/* Theme variants */
.preview-area.theme-dark {
    background: #1a1a2e;
    color: #e0e0e0;
    border-color: #444;
}

.preview-area.theme-dark .preview-card {
    background: #16213e;
}

.preview-area.theme-light {
    background: #ffffff;
    color: #333;
}

.preview-area.theme-system {
    background: #f0f4f8;
    color: #333;
    border-color: #b0bec5;
}

/* Font size variants */
.preview-area.font-small {
    font-size: 0.8rem;
}

.preview-area.font-medium {
    font-size: 1rem;
}

.preview-area.font-large {
    font-size: 1.2rem;
}

/* Compact variant */
.preview-area.compact {
    padding: 0.75rem;
    line-height: 1.3;
}

.preview-area.compact .preview-card {
    padding: 0.5rem;
    margin-top: 0.5rem;
}

